import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    adj = []
    p = 2
    for _ in range(n):
        k = int(data[p])
        p += 1
        adj.append([int(x) - 1 for x in data[p:p + k]])
        p += k
    masks = {0}
    for u in range(n):
        nxt = set(masks)
        for mk in masks:
            for t in adj[u]:
                if not (mk >> t) & 1:
                    nxt.add(mk | (1 << t))
        masks = nxt
    print(max(bin(x).count('1') for x in masks))


main()
